import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import Head from 'next/head';

import { ContentCard, ContentTabs, Icon, PageBanner } from '@openfin/ui-library';
import { enterpriseStyles } from '@openfin/ui-library/enterprise-css-selectors';

import { getBrowserWindow } from '@common/utils/get-browser-window';
import { enterpriseLandingPageTestIds } from '@common/utils/test-ids';
import { trimUrl } from '@common/utils/url';
import { currentOFIdentity } from '@common/utils/window';

import { useBaseUrl } from '@enterprise/utils/base-url-context';

import { formatRecentUrl, getSiteSubTitle } from '@enterprise/components/ControlBar/SearchMenu/utils';
import { useCuratedContent } from '@enterprise/components/LandingPage/useCuratedContent';
import { useLocalTimeState } from '@enterprise/components/LandingPage/useLocalTimeState';
import { useRecentlyVisitedSites } from '@enterprise/components/LandingPage/useRecentlyVisitedSites';

import { NavigationRequest, Site } from '@client-platform/shapes';
import useSystemSchemeCheck from '@common/hooks/useSystemSchemeCheck';
import { VARS } from '@openfin/theme-engine';

import '@openfin/ui-library/enterprise/landing-page/landing-page.css';
import '@openfin/ui-library/shared/content-card.css';
import '@openfin/ui-library/shared/content-tabs.css';
import '@openfin/ui-library/shared/page-banner.css';

const RECENTS_TAB = { id: 'recents', label: 'Recents' } as const;
const FEATURED_TAB = { id: 'featured', label: 'Featured' } as const;

type LandingTabId = typeof RECENTS_TAB.id | typeof FEATURED_TAB.id;

const getSiteIcon = (site: Site): string | React.ReactNode => {
    if (site.type === 'app' || site.type === 'website') {
        return site.icon;
    }
    if (site.type === 'page') {
        return <Icon size="xxlarge" icon="SupertabIcon" />;
    }
    if (site.type === 'collection') {
        return <Icon size="xxlarge" icon="CollectionIcon" />;
    }
    return <Icon size="xxlarge" icon="EnterpriseGlobeIcon" />;
};

const getSiteBottomLabel = (site: Site): string => {
    if (site.type === 'website' && 'url' in site && site.url) {
        return trimUrl(site.url);
    }
    return getSiteSubTitle(site, formatRecentUrl);
};

const stripWordmarkQuotes = (raw: string): string => {
    if (raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"')) {
        return raw.slice(1, -1);
    }
    return raw;
};

/**
 * Landing page for new page active tab — redesigned layout.
 *
 * Structure:
 *   PageBanner (wordmark left, timestamp right)
 *   ContentTabs (Featured always; Recents only when there is at least one recent site)
 *   ContentCard grid
 */
export const LandingPage = () => {
    const { browserBaseUrl } = useBaseUrl();
    const [sites, handleSelectedFeaturedSite] = useCuratedContent();
    const recentlyVisited = useRecentlyVisitedSites();

    const { isSchemeDark } = useSystemSchemeCheck();
    const { dateString, timeString } = useLocalTimeState();

    const readWordmark = useCallback(
        () =>
            stripWordmarkQuotes(
                getComputedStyle(document.documentElement).getPropertyValue(VARS['icon.wordmark']).trim()
            ),
        []
    );

    const [wordmarkUrl, setWordmarkUrl] = useState<string | null>(null);

    useEffect(() => {
        setWordmarkUrl(readWordmark());

        const observer = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                if (mutation.attributeName === 'data-scheme') {
                    setWordmarkUrl(readWordmark());
                }
            }
        });

        observer.observe(document.documentElement, { attributes: true });
        return () => observer.disconnect();
    }, [readWordmark]);

    const [activeTab, setActiveTab] = useState<LandingTabId>(FEATURED_TAB.id);

    const landingTabs = useMemo(
        () => (recentlyVisited.length >= 1 ? [RECENTS_TAB, FEATURED_TAB] : [FEATURED_TAB]),
        [recentlyVisited.length]
    );

    useEffect(() => {
        setActiveTab(landingTabs[0].id as LandingTabId);
    }, [landingTabs]);

    useEffect(() => {
        if (activeTab === RECENTS_TAB.id && recentlyVisited.length === 0) {
            setActiveTab(FEATURED_TAB.id);
        }
    }, [activeTab, recentlyVisited.length]);

    const favicon = `${browserBaseUrl}/enterprise/icons/default-favicon-enterprise-browser-${
        isSchemeDark ? 'dark' : 'light'
    }.svg`;

    const containerRef = useRef<HTMLDivElement>(null);

    const handleRecentSiteClick = useCallback(
        async (index: number) => {
            const site = recentlyVisited[index];
            if (site) {
                const navigationRequest: NavigationRequest = {
                    action: 'result-selected',
                    windowIdentity: currentOFIdentity,
                    viewIdentity: fin.me.identity,
                    site
                };
                const browserWin = await getBrowserWindow();
                // eslint-disable-next-line no-underscore-dangle
                browserWin._handleRequestNavigation(navigationRequest);
            }
        },
        [recentlyVisited]
    );

    const activeSites = useMemo(
        () => (activeTab === RECENTS_TAB.id ? recentlyVisited : sites),
        [activeTab, recentlyVisited, sites]
    );

    const handleCardClick = useCallback(
        (index: number) => {
            if (activeTab === RECENTS_TAB.id) {
                handleRecentSiteClick(index);
            } else {
                handleSelectedFeaturedSite(index);
            }
        },
        [activeTab, handleRecentSiteClick, handleSelectedFeaturedSite]
    );

    return (
        <>
            <Head>
                <title>New Tab</title>
                <link rel="icon" type="image/svg" href={favicon} />
            </Head>
            <div
                ref={containerRef}
                className={`${enterpriseStyles.landingPage} native-scrollbar`}
                data-testid={enterpriseLandingPageTestIds.container}
            >
                <div className={enterpriseStyles.landingPageScrollContent}>
                    <div className={enterpriseStyles.landingPageBannerWrapper}>
                        <PageBanner
                            logo={
                                wordmarkUrl === null ? null : wordmarkUrl ? (
                                    <img src={wordmarkUrl} alt="Company logo" />
                                ) : (
                                    <Icon icon="EnterpriseGlobeIcon" size="xxxxlarge" />
                                )
                            }
                            timestamp={<PageBanner.Timestamp date={dateString} time={timeString} />}
                        />
                    </div>

                    <div className={enterpriseStyles.landingPageTabGridWrapper}>
                        <div className={enterpriseStyles.landingPageStickyTabs}>
                            <ContentTabs
                                tabs={landingTabs}
                                activeTabId={activeTab}
                                onTabChange={(id) => setActiveTab(id as LandingTabId)}
                            />
                        </div>

                        <div
                            className={enterpriseStyles.landingPageCardGrid}
                            data-testid={enterpriseLandingPageTestIds.siteGridContainer}
                        >
                            {activeSites.map((site: Site, idx: number) => (
                                <ContentCard
                                    key={site.id}
                                    icon={getSiteIcon(site)}
                                    title={site.title}
                                    bottomLabel={getSiteBottomLabel(site)}
                                    onClick={() => handleCardClick(idx)}
                                />
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};
